     1→/**
     2→ * FreeLang Nexus - AST 노드 정의
     3→ * V 모드 함수와 Python 모드 함수 통합 AST
     4→ */
     5→
     6→/**
     7→ * 모든 AST 노드의 기본 인터페이스
     8→ */
     9→export interface ASTNode {
    10→  type: string;
    11→  line: number;
    12→  column: number;
    13→  mode: 'v' | 'python' | 'auto';
    14→}
    15→
    16→/**
    17→ * 파라미터 정의
    18→ */
    19→export interface Parameter {
    20→  name: string;
    21→  typeAnnotation?: string; // i64, string 등 (선택)
    22→  line: number;
    23→  column: number;
    24→}
    25→
    26→/**
    27→ * V 모드 함수
    28→ * 예: fn add(x: i64, y: i64) -> i64 { return x + y }
    29→ */
    30→export interface VFunction extends ASTNode {
    31→  type: 'VFunction';
    32→  name: string;
    33→  params: Parameter[];
    34→  returnType?: string; // -> 타입
    35→  body: Statement[];
    36→  mode: 'v';
    37→}
    38→
    39→/**
    40→ * Python 모드 함수
    41→ * 예: def add(a, b): return a + b
    42→ */
    43→export interface PyFunction extends ASTNode {
    44→  type: 'PyFunction';
    45→  name: string;
    46→  params: Parameter[];
    47→  returnType?: string; // -> 타입 (선택)
    48→  body: Statement[];
    49→  mode: 'python';
    50→}
    51→
    52→/**
    53→ * Return 문장
    54→ */
    55→export interface ReturnStatement extends ASTNode {
    56→  type: 'Return';
    57→  value?: Expression;
    58→}
    59→
    60→/**
    61→ * 할당 문장
    62→ */
    63→export interface AssignStatement extends ASTNode {
    64→  type: 'Assign';
    65→  name: string;
    66→  value: Expression;
    67→}
    68→
    69→/**
    70→ * 표현식 문장
    71→ */
    72→export interface ExprStatement extends ASTNode {
    73→  type: 'ExprStatement';
    74→  expression: Expression;
    75→}
    76→
    77→/**
    78→ * If 문장
    79→ */
    80→export interface IfStatement extends ASTNode {
    81→  type: 'IfStatement';
    82→  condition: Expression;
    83→  thenBranch: Statement[];
    84→  elseBranch?: Statement[];
    85→}
    86→
    87→/**
    88→ * 문장 타입 (Return, Assign, ExprStatement, IfStatement)
    89→ */
    90→export type Statement = ReturnStatement | AssignStatement | ExprStatement | IfStatement;
    91→
    92→/**
    93→ * 숫자 리터럴
    94→ */
    95→export interface NumberLiteral extends ASTNode {
    96→  type: 'Number';
    97→  value: number | string; // 16진수, 이진수 표현 가능
    98→}
    99→
   100→/**
   101→ * 문자열 리터럴
   102→ */
   103→export interface StringLiteral extends ASTNode {
   104→  type: 'String';
   105→  value: string;
   106→}
   107→
   108→/**
   109→ * 식별자 (변수명, 함수명 등)
   110→ */
   111→export interface Identifier extends ASTNode {
   112→  type: 'Identifier';
   113→  name: string;
   114→}
   115→
   116→/**
   117→ * 이항 연산식
   118→ * 예: x + y, a * b
   119→ */
   120→export interface BinaryExpr extends ASTNode {
   121→  type: 'BinaryExpr';
   122→  left: Expression;
   123→  operator: string; // +, -, *, /, &&, ||, ==, !=, <, >, <=, >=
   124→  right: Expression;
   125→}
   126→
   127→/**
   128→ * 함수 호출 표현식
   129→ * 예: foo(), Module::func()
   130→ */
   131→export interface CallExpr extends ASTNode {
   132→  type: 'Call';
   133→  callee: Expression | string; // Identifier 또는 Module::func 형식 문자열
   134→  args: Expression[];
   135→}
   136→
   137→/**
   138→ * 배열 리터럴
   139→ * 예: [1, 2, 3], []
   140→ */
   141→export interface ArrayLiteral extends ASTNode {
   142→  type: 'Array';
   143→  elements: Expression[];
   144→}
   145→
   146→/**
   147→ * 배열 접근
   148→ * 예: arr[0], items[i]
   149→ */
   150→export interface ArrayAccess extends ASTNode {
   151→  type: 'ArrayAccess';
   152→  object: Expression;
   153→  index: Expression;
   154→}
   155→
   156→/**
   157→ * 표현식 타입
   158→ */
   159→export type Expression = NumberLiteral | StringLiteral | Identifier | BinaryExpr | CallExpr | ArrayLiteral | ArrayAccess;
   160→
   161→/**
   162→ * 프로그램 (최상위 노드)
   163→ */
   164→export interface Program {
   165→  type: 'Program';
   166→  body: Array<VFunction | PyFunction | Statement>;
   167→}
   168→

