     1→/**
     2→ * FreeLang Nexus - 통합 Parser
     3→ * V 모드 + Python 모드 함수를 혼합하여 파싱
     4→ */
     5→
     6→import { Token, TokenType } from '../lexer/token';
     7→import * as AST from './ast';
     8→
     9→export class NexusParser {
    10→  private tokens: Token[];
    11→  private pos: number = 0;
    12→
    13→  constructor(tokens: Token[]) {
    14→    this.tokens = tokens;
    15→  }
    16→
    17→  /**
    18→   * 파싱 진입점
    19→   */
    20→  parse(): AST.Program {
    21→    const body: Array<AST.VFunction | AST.PyFunction | AST.Statement> = [];
    22→
    23→    while (!this.isAtEnd()) {
    24→      this.skipNewlines();
    25→      if (this.isAtEnd()) break;
    26→
    27→      const token = this.peek();
    28→
    29→      // @mode 마커는 스킵 (이미 렉서에서 처리됨)
    30→      if (token.type === TokenType.MODE_MARKER) {
    31→        this.advance();
    32→        continue;
    33→      }
    34→
    35→      // 탑레벨 아이템 파싱
    36→      const item = this.parseTopLevel();
    37→      if (item) {
    38→        body.push(item);
    39→      }
    40→    }
    41→
    42→    return { type: 'Program', body };
    43→  }
    44→
    45→  /**
    46→   * 탑레벨 아이템 파싱
    47→   * V 함수, Python 함수, 또는 문장
    48→   */
    49→  private parseTopLevel(): AST.VFunction | AST.PyFunction | AST.Statement | null {
    50→    const token = this.peek();
    51→
    52→    // V 모드 함수
    53→    if (token.type === TokenType.FN) {
    54→      return this.parseVFunction();
    55→    }
    56→
    57→    // Python 모드 함수
    58→    if (token.type === TokenType.DEF) {
    59→      return this.parsePyFunction();
    60→    }
    61→
    62→    // 그 외: 문장
    63→    return this.parseStatement();
    64→  }
    65→
    66→  /**
    67→   * V 함수 파싱
    68→   * fn name(params) -> type { body }
    69→   */
    70→  private parseVFunction(): AST.VFunction {
    71→    const startToken = this.consume(TokenType.FN, 'fn 키워드 필요');
    72→    const nameToken = this.consume(TokenType.IDENTIFIER, '함수명 필요');
    73→    const name = nameToken.value;
    74→
    75→    this.consume(TokenType.LPAREN, '( 필요');
    76→    const params = this.parseVParams();
    77→    this.consume(TokenType.RPAREN, ') 필요');
    78→
    79→    const returnType = this.parseReturnType();
    80→
    81→    this.consume(TokenType.LBRACE, '{ 필요');
    82→    const body = this.parseVBlock();
    83→    this.consume(TokenType.RBRACE, '} 필요');
    84→
    85→    return {
    86→      type: 'VFunction',
    87→      name,
    88→      params,
    89→      returnType,
    90→      body,
    91→      mode: 'v',
    92→      line: startToken.line,
    93→      column: startToken.column,
    94→    };
    95→  }
    96→
    97→  /**
    98→   * Python 함수 파싱
    99→   * def name(params): INDENT body DEDENT
   100→   */
   101→  private parsePyFunction(): AST.PyFunction {
   102→    const startToken = this.consume(TokenType.DEF, 'def 키워드 필요');
   103→    const nameToken = this.consume(TokenType.IDENTIFIER, '함수명 필요');
   104→    const name = nameToken.value;
   105→
   106→    this.consume(TokenType.LPAREN, '( 필요');
   107→    const params = this.parsePyParams();
   108→    this.consume(TokenType.RPAREN, ') 필요');
   109→
   110→    const returnType = this.parseReturnType();
   111→
   112→    this.consume(TokenType.COLON, ': 필요');
   113→    this.skipNewlines();
   114→
   115→    const body = this.parsePyBlock();
   116→
   117→    return {
   118→      type: 'PyFunction',
   119→      name,
   120→      params,
   121→      returnType,
   122→      body,
   123→      mode: 'python',
   124→      line: startToken.line,
   125→      column: startToken.column,
   126→    };
   127→  }
   128→
   129→  /**
   130→   * V 함수 파라미터 파싱
   131→   * (x: i64, y: i64)
   132→   */
   133→  private parseVParams(): AST.Parameter[] {
   134→    const params: AST.Parameter[] = [];
   135→
   136→    while (!this.check(TokenType.RPAREN) && !this.isAtEnd()) {
   137→      const nameToken = this.consume(TokenType.IDENTIFIER, '파라미터명 필요');
   138→      this.consume(TokenType.COLON, ': 필요');
   139→      const typeToken = this.peek();
   140→      const typeAnnotation = this.parseType();
   141→
   142→      params.push({
   143→        name: nameToken.value,
   144→        typeAnnotation,
   145→        line: nameToken.line,
   146→        column: nameToken.column,
   147→      });
   148→
   149→      if (!this.check(TokenType.RPAREN)) {
   150→        this.consume(TokenType.COMMA, ', 필요');
   151→      }
   152→    }
   153→
   154→    return params;
   155→  }
   156→
   157→  /**
   158→   * Python 함수 파라미터 파싱
   159→   * (x, y) 또는 (x: int, y: int)
   160→   */
   161→  private parsePyParams(): AST.Parameter[] {
   162→    const params: AST.Parameter[] = [];
   163→
   164→    while (!this.check(TokenType.RPAREN) && !this.isAtEnd()) {
   165→      const nameToken = this.consume(TokenType.IDENTIFIER, '파라미터명 필요');
   166→      let typeAnnotation: string | undefined;
   167→
   168→      // 타입 어노테이션 (선택)
   169→      if (this.check(TokenType.COLON)) {
   170→        this.advance();
   171→        typeAnnotation = this.parseType();
   172→      }
   173→
   174→      params.push({
   175→        name: nameToken.value,
   176→        typeAnnotation,
   177→        line: nameToken.line,
   178→        column: nameToken.column,
   179→      });
   180→
   181→      if (!this.check(TokenType.RPAREN)) {
   182→        this.consume(TokenType.COMMA, ', 필요');
   183→      }
   184→    }
   185→
   186→    return params;
   187→  }
   188→
   189→  /**
   190→   * 반환 타입 파싱
   191→   * -> i64 (선택)
   192→   */
   193→  private parseReturnType(): string | undefined {
   194→    if (this.match(TokenType.ARROW)) {
   195→      return this.parseType();
   196→    }
   197→    return undefined;
   198→  }
   199→
   200→  /**
   201→   * 타입 파싱
   202→   * i64, string, bool 등
   203→   */
   204→  private parseType(): string {
   205→    const token = this.peek();
   206→
   207→    // 기본 타입
   208→    if (
   209→      token.type === TokenType.I64 ||
   210→      token.type === TokenType.I32 ||
   211→      token.type === TokenType.F64 ||
   212→      token.type === TokenType.BOOL ||
   213→      token.type === TokenType.STRING ||
   214→      token.type === TokenType.IDENTIFIER
   215→    ) {
   216→      return this.advance().value;
   217→    }
   218→
   219→    throw new Error(`타입 필요 at line ${token.line}`);
   220→  }
   221→
   222→  /**
   223→   * V 블록 파싱
   224→   * { statements }
   225→   */
   226→  private parseVBlock(): AST.Statement[] {
   227→    const statements: AST.Statement[] = [];
   228→
   229→    while (!this.check(TokenType.RBRACE) && !this.isAtEnd()) {
   230→      this.skipNewlines();
   231→
   232→      if (this.check(TokenType.RBRACE)) break;
   233→
   234→      const stmt = this.parseStatement();
   235→      if (stmt) {
   236→        statements.push(stmt);
   237→      }
   238→
   239→      this.skipNewlines();
   240→    }
   241→
   242→    return statements;
   243→  }
   244→
   245→  /**
   246→   * Python 블록 파싱
   247→   * INDENT statements DEDENT
   248→   */
   249→  private parsePyBlock(): AST.Statement[] {
   250→    const statements: AST.Statement[] = [];
   251→
   252→    this.consume(TokenType.INDENT, 'INDENT 필요');
   253→
   254→    while (!this.check(TokenType.DEDENT) && !this.isAtEnd()) {
   255→      this.skipNewlines();
   256→
   257→      if (this.check(TokenType.DEDENT) || this.isAtEnd()) break;
   258→
   259→      const stmt = this.parseStatement();
   260→      if (stmt) {
   261→        statements.push(stmt);
   262→      }
   263→
   264→      this.skipNewlines();
   265→    }
   266→
   267→    // DEDENT 또는 EOF 모두 허용 (파일 끝에서 DEDENT가 항상 생성되지 않을 수 있음)
   268→    if (this.check(TokenType.DEDENT)) {
   269→      this.advance();
   270→    }
   271→
   272→    return statements;
   273→  }
   274→
   275→  /**
   276→   * 문장 파싱
   277→   */
   278→  private parseStatement(): AST.Statement {
   279→    const token = this.peek();
   280→
   281→    // return 문장
   282→    if (token.type === TokenType.RETURN) {
   283→      return this.parseReturnStatement();
   284→    }
   285→
   286→    // if 문장
   287→    if (token.type === TokenType.IF) {
   288→      return this.parseIfStatement();
   289→    }
   290→
   291→    // pass 문장 (Python)
   292→    if (token.type === TokenType.PASS) {
   293→      const passToken = this.advance();
   294→      return {
   295→        type: 'ExprStatement',
   296→        expression: {
   297→          type: 'Identifier',
   298→          name: 'pass',
   299→          line: passToken.line,
   300→          column: passToken.column,
   301→          mode: passToken.mode,
   302→        },
   303→        line: passToken.line,
   304→        column: passToken.column,
   305→        mode: passToken.mode,
   306→      };
   307→    }
   308→
   309→    // let 또는 식별자 (할당 가능성)
   310→    if (token.type === TokenType.LET || token.type === TokenType.IDENTIFIER) {
   311→      return this.parseAssignOrExpr();
   312→    }
   313→
   314→    // 기본값: 표현식 문장
   315→    const expr = this.parseExpression();
   316→    const startToken = this.peek();
   317→    return {
   318→      type: 'ExprStatement',
   319→      expression: expr,
   320→      line: startToken.line,
   321→      column: startToken.column,
   322→      mode: startToken.mode,
   323→    };
   324→  }
   325→
   326→  /**
   327→   * Return 문장 파싱
   328→   */
   329→  private parseReturnStatement(): AST.ReturnStatement {
   330→    const startToken = this.consume(TokenType.RETURN, 'return 필요');
   331→    let value: AST.Expression | undefined;
   332→
   333→    // 반환값이 있으면 파싱
   334→    if (!this.check(TokenType.NEWLINE) && !this.check(TokenType.DEDENT) && !this.check(TokenType.RBRACE)) {
   335→      value = this.parseExpression();
   336→    }
   337→
   338→    return {
   339→      type: 'Return',
   340→      value,
   341→      line: startToken.line,
   342→      column: startToken.column,
   343→      mode: startToken.mode,
   344→    };
   345→  }
   346→
   347→  /**
   348→   * 할당 또는 표현식 파싱
   349→   */
   350→  private parseAssignOrExpr(): AST.Statement {
   351→    const startToken = this.peek();
   352→
   353→    // let x = value
   354→    if (startToken.type === TokenType.LET) {
   355→      this.advance();
   356→      const nameToken = this.consume(TokenType.IDENTIFIER, '변수명 필요');
   357→      this.consume(TokenType.EQUAL, '= 필요');
   358→      const value = this.parseExpression();
   359→
   360→      return {
   361→        type: 'Assign',
   362→        name: nameToken.value,
   363→        value,
   364→        line: startToken.line,
   365→        column: startToken.column,
   366→        mode: startToken.mode,
   367→      };
   368→    }
   369→
   370→    // x = value 또는 함수호출 등
   371→    if (startToken.type === TokenType.IDENTIFIER) {
   372→      const nameToken = this.peek();
   373→      const name = nameToken.value;
   374→      this.advance();
   375→
   376→      if (this.check(TokenType.EQUAL)) {
   377→        this.advance();
   378→        const value = this.parseExpression();
   379→
   380→        return {
   381→          type: 'Assign',
   382→          name,
   383→          value,
   384→          line: startToken.line,
   385→          column: startToken.column,
   386→          mode: startToken.mode,
   387→        };
   388→      }
   389→
   390→      // 아니면 전체 표현식으로 다시 파싱 (함수호출 등 포함)
   391→      // pos를 한 칸 뒤로 이동하여 식별자부터 다시 파싱
   392→      this.pos--;
   393→      const expr = this.parseExpression();
   394→
   395→      return {
   396→        type: 'ExprStatement',
   397→        expression: expr,
   398→        line: startToken.line,
   399→        column: startToken.column,
   400→        mode: startToken.mode,
   401→      };
   402→    }
   403→
   404→    throw new Error(`예상치 못한 토큰 at line ${startToken.line}`);
   405→  }
   406→
   407→  /**
   408→   * If 문장 파싱
   409→   * if condition { body } [else { body }]
   410→   */
   411→  private parseIfStatement(): AST.IfStatement {
   412→    const startToken = this.consume(TokenType.IF, 'if 키워드 필요');
   413→    const condition = this.parseExpression();
   414→    this.consume(TokenType.LBRACE, '{ 필요');
   415→    const thenBranch = this.parseVBlock();
   416→    this.consume(TokenType.RBRACE, '} 필요');
   417→
   418→    let elseBranch: AST.Statement[] | undefined;
   419→    if (this.match(TokenType.ELSE)) {
   420→      this.consume(TokenType.LBRACE, '{ 필요');
   421→      elseBranch = this.parseVBlock();
   422→      this.consume(TokenType.RBRACE, '} 필요');
   423→    }
   424→
   425→    return {
   426→      type: 'IfStatement',
   427→      condition,
   428→      thenBranch,
   429→      elseBranch,
   430→      line: startToken.line,
   431→      column: startToken.column,
   432→      mode: startToken.mode,
   433→    };
   434→  }
   435→
   436→  /**
   437→   * 표현식 파싱
   438→   * 간단한 구현: 곱셈/나눗셈 → 덧셈/뺄셈 → 비교/논리
   439→   */
   440→  private parseExpression(): AST.Expression {
   441→    return this.parseLogicalOr();
   442→  }
   443→
   444→  /**
   445→   * 논리 OR 파싱: ||
   446→   */
   447→  private parseLogicalOr(): AST.Expression {
   448→    let expr = this.parseLogicalAnd();
   449→
   450→    while (this.match(TokenType.OR)) {
   451→      const operator = this.previous().value;
   452→      const right = this.parseLogicalAnd();
   453→      const token = this.previous();
   454→      expr = {
   455→        type: 'BinaryExpr',
   456→        left: expr,
   457→        operator,
   458→        right,
   459→        line: token.line,
   460→        column: token.column,
   461→        mode: token.mode,
   462→      };
   463→    }
   464→
   465→    return expr;
   466→  }
   467→
   468→  /**
   469→   * 논리 AND 파싱: &&
   470→   */
   471→  private parseLogicalAnd(): AST.Expression {
   472→    let expr = this.parseEquality();
   473→
   474→    while (this.match(TokenType.AND)) {
   475→      const operator = this.previous().value;
   476→      const right = this.parseEquality();
   477→      const token = this.previous();
   478→      expr = {
   479→        type: 'BinaryExpr',
   480→        left: expr,
   481→        operator,
   482→        right,
   483→        line: token.line,
   484→        column: token.column,
   485→        mode: token.mode,
   486→      };
   487→    }
   488→
   489→    return expr;
   490→  }
   491→
   492→  /**
   493→   * 등호/부등호 파싱: ==, !=
   494→   */
   495→  private parseEquality(): AST.Expression {
   496→    let expr = this.parseComparison();
   497→
   498→    while (this.match(TokenType.EQ, TokenType.NE)) {
   499→      const operator = this.previous().value;
   500→      const right = this.parseComparison();
   501→      const token = this.previous();
   502→      expr = {
   503→        type: 'BinaryExpr',
   504→        left: expr,
   505→        operator,
   506→        right,
   507→        line: token.line,
   508→        column: token.column,
   509→        mode: token.mode,
   510→      };
   511→    }
   512→
   513→    return expr;
   514→  }
   515→
   516→  /**
   517→   * 비교 파싱: <, >, <=, >=
   518→   */
   519→  private parseComparison(): AST.Expression {
   520→    let expr = this.parseAddition();
   521→
   522→    while (this.match(TokenType.LT, TokenType.GT, TokenType.LE, TokenType.GE)) {
   523→      const operator = this.previous().value;
   524→      const right = this.parseAddition();
   525→      const token = this.previous();
   526→      expr = {
   527→        type: 'BinaryExpr',
   528→        left: expr,
   529→        operator,
   530→        right,
   531→        line: token.line,
   532→        column: token.column,
   533→        mode: token.mode,
   534→      };
   535→    }
   536→
   537→    return expr;
   538→  }
   539→
   540→  /**
   541→   * 덧셈/뺄셈 파싱
   542→   */
   543→  private parseAddition(): AST.Expression {
   544→    let expr = this.parseMultiplication();
   545→
   546→    while (this.match(TokenType.PLUS, TokenType.MINUS)) {
   547→      const operator = this.previous().value;
   548→      const right = this.parseMultiplication();
   549→      const token = this.previous();
   550→      expr = {
   551→        type: 'BinaryExpr',
   552→        left: expr,
   553→        operator,
   554→        right,
   555→        line: token.line,
   556→        column: token.column,
   557→        mode: token.mode,
   558→      };
   559→    }
   560→
   561→    return expr;
   562→  }
   563→
   564→  /**
   565→   * 곱셈/나눗셈 파싱
   566→   */
   567→  private parseMultiplication(): AST.Expression {
   568→    let expr = this.parseUnary();
   569→
   570→    while (this.match(TokenType.STAR, TokenType.SLASH)) {
   571→      const operator = this.previous().value;
   572→      const right = this.parseUnary();
   573→      const token = this.previous();
   574→      expr = {
   575→        type: 'BinaryExpr',
   576→        left: expr,
   577→        operator,
   578→        right,
   579→        line: token.line,
   580→        column: token.column,
   581→        mode: token.mode,
   582→      };
   583→    }
   584→
   585→    return expr;
   586→  }
   587→
   588→  /**
   589→   * 단항 연산 파싱
   590→   */
   591→  private parseUnary(): AST.Expression {
   592→    // TODO: 단항 연산자 (-, !, ~) 처리 가능
   593→    return this.parsePostfix();
   594→  }
   595→
   596→  /**
   597→   * 후위 연산 파싱 (함수 호출, 배열 접근)
   598→   */
   599→  private parsePostfix(): AST.Expression {
   600→    let expr = this.parsePrimary();
   601→
   602→    while (true) {
   603→      // 함수 호출: foo()
   604→      if (this.match(TokenType.LPAREN)) {
   605→        const args = this.parseArguments();
   606→        this.consume(TokenType.RPAREN, ') 필요');
   607→
   608→        const token = this.previous();
   609→        expr = {
   610→          type: 'Call',
   611→          callee: expr,
   612→          args,
   613→          line: token.line,
   614→          column: token.column,
   615→          mode: token.mode,
   616→        };
   617→      }
   618→      // 배열 인덱싱: arr[0]
   619→      else if (this.match(TokenType.LBRACKET)) {
   620→        const index = this.parseExpression();
   621→        const token = this.consume(TokenType.RBRACKET, '] 필요');
   622→
   623→        expr = {
   624→          type: 'ArrayAccess',
   625→          object: expr,
   626→          index,
   627→          line: token.line,
   628→          column: token.column,
   629→          mode: token.mode,
   630→        };
   631→      } else {
   632→        break;
   633→      }
   634→    }
   635→
   636→    return expr;
   637→  }
   638→
   639→  /**
   640→   * 기본 표현식 파싱 (리터럴, 식별자 등)
   641→   */
   642→  private parsePrimary(): AST.Expression {
   643→    const token = this.peek();
   644→
   645→    // 숫자
   646→    if (token.type === TokenType.NUMBER) {
   647→      this.advance();
   648→      return {
   649→        type: 'Number',
   650→        value: token.value,
   651→        line: token.line,
   652→        column: token.column,
   653→        mode: token.mode,
   654→      };
   655→    }
   656→
   657→    // 문자열
   658→    if (token.type === TokenType.STRING) {
   659→      this.advance();
   660→      return {
   661→        type: 'String',
   662→        value: token.value,
   663→        line: token.line,
   664→        column: token.column,
   665→        mode: token.mode,
   666→      };
   667→    }
   668→
   669→    // true, false
   670→    if (token.type === TokenType.TRUE || token.type === TokenType.FALSE) {
   671→      this.advance();
   672→      return {
   673→        type: 'Number',
   674→        value: token.type === TokenType.TRUE ? 1 : 0,
   675→        line: token.line,
   676→        column: token.column,
   677→        mode: token.mode,
   678→      };
   679→    }
   680→
   681→    // 배열 리터럴: [1, 2, 3]
   682→    if (token.type === TokenType.LBRACKET) {
   683→      return this.parseArrayLiteral();
   684→    }
   685→
   686→    // 식별자
   687→    if (token.type === TokenType.IDENTIFIER) {
   688→      this.advance();
   689→      return {
   690→        type: 'Identifier',
   691→        name: token.value,
   692→        line: token.line,
   693→        column: token.column,
   694→        mode: token.mode,
   695→      };
   696→    }
   697→
   698→    // 괄호 식
   699→    if (this.match(TokenType.LPAREN)) {
   700→      const expr = this.parseExpression();
   701→      this.consume(TokenType.RPAREN, ') 필요');
   702→      return expr;
   703→    }
   704→
   705→    throw new Error(`예상치 못한 토큰: ${token.value} at line ${token.line}`);
   706→  }
   707→
   708→  /**
   709→   * 배열 리터럴 파싱
   710→   * [1, 2, 3], [], [a+b, c*d], [1, 2,] (trailing comma 지원)
   711→   */
   712→  private parseArrayLiteral(): AST.ArrayLiteral {
   713→    const startToken = this.consume(TokenType.LBRACKET, '[');
   714→    const elements: AST.Expression[] = [];
   715→
   716→    // 빈 배열 또는 요소들
   717→    while (!this.check(TokenType.RBRACKET) && !this.isAtEnd()) {
   718→      elements.push(this.parseExpression());
   719→
   720→      // 쉼표가 있으면 계속, 없으면 종료
   721→      if (!this.match(TokenType.COMMA)) {
   722→        break;
   723→      }
   724→
   725→      // trailing comma: 쉼표 뒤에 ] 가 있으면 즉시 종료
   726→      if (this.check(TokenType.RBRACKET)) {
   727→        break;
   728→      }
   729→    }
   730→
   731→    const endToken = this.consume(TokenType.RBRACKET, '] 필요');
   732→
   733→    return {
   734→      type: 'Array',
   735→      elements,
   736→      line: startToken.line,
   737→      column: startToken.column,
   738→      mode: startToken.mode,
   739→    };
   740→  }
   741→
   742→  /**
   743→   * 함수 호출 인자 파싱
   744→   */
   745→  private parseArguments(): AST.Expression[] {
   746→    const args: AST.Expression[] = [];
   747→
   748→    if (!this.check(TokenType.RPAREN)) {
   749→      do {
   750→        args.push(this.parseExpression());
   751→      } while (this.match(TokenType.COMMA));
   752→    }
   753→
   754→    return args;
   755→  }
   756→
   757→  // ========== 헬퍼 메서드 ==========
   758→
   759→  private peek(): Token {
   760→    if (this.pos >= this.tokens.length) {
   761→      return this.tokens[this.tokens.length - 1]; // EOF 토큰
   762→    }
   763→    return this.tokens[this.pos];
   764→  }
   765→
   766→  private advance(): Token {
   767→    if (!this.isAtEnd()) {
   768→      this.pos++;
   769→    }
   770→    return this.previous();
   771→  }
   772→
   773→  private previous(): Token {
   774→    return this.tokens[this.pos - 1];
   775→  }
   776→
   777→  private isAtEnd(): boolean {
   778→    return this.peek().type === TokenType.EOF;
   779→  }
   780→
   781→  private check(type: TokenType): boolean {
   782→    if (this.isAtEnd()) return false;
   783→    return this.peek().type === type;
   784→  }
   785→
   786→  private match(...types: TokenType[]): boolean {
   787→    for (const type of types) {
   788→      if (this.check(type)) {
   789→        this.advance();
   790→        return true;
   791→      }
   792→    }
   793→    return false;
   794→  }
   795→
   796→  private consume(type: TokenType, message: string): Token {
   797→    if (this.check(type)) return this.advance();
   798→
   799→    const token = this.peek();
   800→    throw new Error(`${message} at line ${token.line}, got ${token.value}`);
   801→  }
   802→
   803→  private skipNewlines(): void {
   804→    while (this.match(TokenType.NEWLINE)) {
   805→      // 계속
   806→    }
   807→  }
   808→}
